import { CHARSET_MAP, GENERATOR } from './charset.mjs';

function isPrintableAscii(text) {
  for (const character of text) {
    const codePoint = character.charCodeAt(0);

    if (codePoint < 33 || codePoint > 126) {
      return false;
    }
  }

  return true;
}

function isMixedCase(text) {
  return text !== text.toLowerCase() && text !== text.toUpperCase();
}

export function bech32Polymod(values) {
  let checksum = 1;

  for (const value of values) {
    const top = checksum >> 25;
    checksum = ((checksum & 0x1ffffff) << 5) ^ value;

    for (let index = 0; index < GENERATOR.length; index += 1) {
      if ((top >> index) & 1) {
        checksum ^= GENERATOR[index];
      }
    }
  }

  return checksum;
}

export function bech32HrpExpand(hrp) {
  const highBits = [];
  const lowBits = [];

  for (const character of hrp) {
    const codePoint = character.charCodeAt(0);
    highBits.push(codePoint >> 5);
    lowBits.push(codePoint & 31);
  }

  return [...highBits, 0, ...lowBits];
}

export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod([...bech32HrpExpand(hrp), ...data]) === 1;
}

export function bech32Decode(bech) {
  if (!isPrintableAscii(bech) || isMixedCase(bech)) {
    return [null, null];
  }

  const normalized = bech.toLowerCase();
  const separatorIndex = normalized.lastIndexOf('1');

  if (separatorIndex < 1 || separatorIndex + 7 > normalized.length || normalized.length > 90) {
    return [null, null];
  }

  const hrp = normalized.slice(0, separatorIndex);
  const dataSection = normalized.slice(separatorIndex + 1);
  const data = [];

  for (const character of dataSection) {
    const value = CHARSET_MAP.get(character);

    if (value === undefined) {
      return [null, null];
    }

    data.push(value);
  }

  if (!bech32VerifyChecksum(hrp, data)) {
    return [null, null];
  }

  return [hrp, data.slice(0, -6)];
}

import path from 'node:path';

const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;
const HELP_DISPLAY = '-h/--help';

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B\n`;
}

export function buildHelp(programName) {
  return `${buildUsage(programName)}
options:
  -h, --help  show this help message and exit
  --a A
  --b B
`;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}${programName}: error: ${message}\n`;
}

function getProgramName(scriptPath) {
  return path.basename(scriptPath || 'test5.mjs');
}

function isNegativeNumberLike(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function splitToken(token) {
  const equalsIndex = token.indexOf('=');

  if (equalsIndex === -1) {
    return { option: token, attachedValue: null };
  }

  return {
    option: token.slice(0, equalsIndex),
    attachedValue: token.slice(equalsIndex + 1),
  };
}

function isLongHelpOption(option) {
  return option.startsWith('--h') && '--help'.startsWith(option);
}

function isHelpToken(token) {
  if (token === '-h') {
    return { kind: 'help' };
  }

  if (token.startsWith('-h=')) {
    return { kind: 'help_explicit_argument', explicitArgument: token.slice(3) };
  }

  if (token.startsWith('-h')) {
    return { kind: 'help' };
  }

  const { option, attachedValue } = splitToken(token);

  if (!isLongHelpOption(option)) {
    return null;
  }

  if (attachedValue !== null) {
    return { kind: 'help_explicit_argument', explicitArgument: attachedValue };
  }

  return { kind: 'help' };
}

function tokenLooksLikeOption(token) {
  if (token === '--') {
    return true;
  }

  if (!token.startsWith('-')) {
    return false;
  }

  return !isNegativeNumberLike(token);
}

function readOptionValue(argv, index, optionName, programName) {
  const nextToken = argv[index + 1];

  if (nextToken === undefined || tokenLooksLikeOption(nextToken)) {
    return {
      exitCode: 2,
      stream: 'stderr',
      text: buildError(programName, `argument ${optionName}: expected one argument`),
    };
  }

  return {
    nextIndex: index + 1,
    value: nextToken,
  };
}

export function parseTest5Arguments(argv, scriptPath) {
  const programName = getProgramName(scriptPath);
  const values = {
    a: undefined,
    b: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    const helpToken = isHelpToken(token);

    if (helpToken !== null) {
      if (helpToken.kind === 'help_explicit_argument') {
        return {
          exitCode: 2,
          stream: 'stderr',
          text: buildError(
            programName,
            `argument ${HELP_DISPLAY}: ignored explicit argument '${helpToken.explicitArgument}'`,
          ),
        };
      }

      return {
        exitCode: 0,
        stream: 'stdout',
        text: buildHelp(programName),
      };
    }

    const { option, attachedValue } = splitToken(token);

    if (option === '--a' || option === '--b') {
      if (attachedValue !== null) {
        values[option.slice(2)] = attachedValue;
        continue;
      }

      const optionValue = readOptionValue(argv, index, option, programName);

      if ('exitCode' in optionValue) {
        return optionValue;
      }

      values[option.slice(2)] = optionValue.value;
      index = optionValue.nextIndex;
      continue;
    }

    extras.push(token);
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    return {
      exitCode: 2,
      stream: 'stderr',
      text: buildError(
        programName,
        `the following arguments are required: ${missing.join(', ')}`,
      ),
    };
  }

  if (extras.length > 0) {
    return {
      exitCode: 2,
      stream: 'stderr',
      text: buildError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    values,
  };
}

import { pathToFileURL } from 'node:url';
import { parseTest5Arguments } from './lib/cli/argparse_compat.mjs';
import { decodeSegwitAddress } from './lib/bech32/segwit.mjs';
import { formatPythonTuple } from './lib/format/python_repr.mjs';

function writeOutput(stream, text) {
  if (stream === 'stderr') {
    process.stderr.write(text);
    return;
  }

  process.stdout.write(text);
}

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const parsed = parseTest5Arguments(argv, scriptPath);

  if ('exitCode' in parsed) {
    writeOutput(parsed.stream, parsed.text);
    process.exitCode = parsed.exitCode;
    return;
  }

  const result = decodeSegwitAddress(parsed.values.a, parsed.values.b);
  process.stdout.write(`${formatPythonTuple(result)}\n`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}

import { bech32Decode } from './core.mjs';

export function convertBits(data, fromBits, toBits, pad = true) {
  let accumulator = 0;
  let bits = 0;
  const converted = [];
  const maxValue = (1 << toBits) - 1;
  const maxAccumulator = (1 << (fromBits + toBits - 1)) - 1;

  for (const value of data) {
    if (value < 0 || (value >> fromBits) !== 0) {
      return null;
    }

    accumulator = ((accumulator << fromBits) | value) & maxAccumulator;
    bits += fromBits;

    while (bits >= toBits) {
      bits -= toBits;
      converted.push((accumulator >> bits) & maxValue);
    }
  }

  if (pad) {
    if (bits > 0) {
      converted.push((accumulator << (toBits - bits)) & maxValue);
    }
  } else if (bits >= fromBits || ((accumulator << (toBits - bits)) & maxValue) !== 0) {
    return null;
  }

  return converted;
}

export function decodeSegwitAddress(expectedHrp, address) {
  const [actualHrp, data] = bech32Decode(address);

  if (actualHrp !== expectedHrp) {
    return [null, null];
  }

  const decoded = convertBits(data.slice(1), 5, 8, false);

  if (decoded === null || decoded.length < 2 || decoded.length > 40) {
    return [null, null];
  }

  const witnessVersion = data[0];

  if (witnessVersion > 16) {
    return [null, null];
  }

  if (witnessVersion === 0 && decoded.length !== 20 && decoded.length !== 32) {
    return [null, null];
  }

  return [witnessVersion, decoded];
}

export function formatPythonValue(value) {
  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatPythonValue(item)).join(', ')}]`;
  }

  return String(value);
}

export function formatPythonTuple(values) {
  return `(${values.map((value) => formatPythonValue(value)).join(', ')})`;
}

const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;

const TEST5_OPTIONS = [
  { name: "--a", metavar: "A", required: true, dest: "a" },
  { name: "--b", metavar: "B", required: true, dest: "b" },
];

function buildUsageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function buildHelpText(programName) {
  return [
    buildUsageLine(programName),
    "",
    "options:",
    "  -h, --help  show this help message and exit",
    "  --a A",
    "  --b B",
    "",
  ].join("\n");
}

function buildErrorText(programName, message) {
  return `${buildUsageLine(programName)}\n${programName}: error: ${message}\n`;
}

function isOptionLikeToken(token) {
  return token.startsWith("-") && token !== "-" && !NEGATIVE_NUMBER_PATTERN.test(token);
}

function hasHelpPrefix(token) {
  return token.startsWith("-h") && !token.startsWith("--");
}

export function parseTest5Arguments(argv, programName) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "-h" || token === "--help" || hasHelpPrefix(token)) {
      return { kind: "help", text: buildHelpText(programName) };
    }

    if (token.startsWith("--help=")) {
      return {
        kind: "error",
        exitCode: 2,
        text: buildErrorText(
          programName,
          `argument -h/--help: ignored explicit argument '${token.slice(7)}'`,
        ),
      };
    }

    if (token === "--") {
      extras.push(...argv.slice(index));
      break;
    }

    if (token.startsWith("--")) {
      const equalsIndex = token.indexOf("=");
      const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const option = TEST5_OPTIONS.find((candidate) => candidate.name === optionName);

      if (!option) {
        extras.push(token);
        continue;
      }

      if (equalsIndex !== -1) {
        values[option.dest] = token.slice(equalsIndex + 1);
        continue;
      }

      const nextToken = argv[index + 1];
      if (
        nextToken === undefined ||
        nextToken === "--" ||
        isOptionLikeToken(nextToken)
      ) {
        return {
          kind: "error",
          exitCode: 2,
          text: buildErrorText(programName, `argument ${option.name}: expected one argument`),
        };
      }

      values[option.dest] = nextToken;
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = TEST5_OPTIONS.filter((option) => !(option.dest in values)).map(
    (option) => option.name,
  );
  if (missing.length > 0) {
    return {
      kind: "error",
      exitCode: 2,
      text: buildErrorText(
        programName,
        `the following arguments are required: ${missing.join(", ")}`,
      ),
    };
  }

  if (extras.length > 0) {
    return {
      kind: "error",
      exitCode: 2,
      text: buildErrorText(programName, `unrecognized arguments: ${extras.join(" ")}`),
    };
  }

  return { kind: "ok", values };
}
